# Hypothesis: a plain int attribute satisfies a read-only property in a protocol, and generic protocol functions infer str for both a structural and a nominal match.
from typing import Protocol, TypeVar, reveal_type

T = TypeVar("T")


class Sized(Protocol):
    @property
    def size(self) -> int: ...


class Source(Protocol[T]):
    def get(self) -> T: ...


class Box:
    size: int = 3

    def __init__(self, value: str) -> None:
        self.value = value

    def get(self) -> str:
        return self.value


class Impl(Source[str]):
    def get(self) -> str:
        return "x"


def measure(item: Sized) -> int:
    return item.size


def first(src: Source[T]) -> T:
    return src.get()


def twice(src: Source[T]) -> tuple[T, T]:
    return (src.get(), src.get())


box = Box("hi")
reveal_type(measure(box))
reveal_type(first(box))
impl = Impl()
reveal_type(twice(impl))
reveal_type(first(impl))
assert measure(box) == 3
assert first(box) == "hi"
assert twice(impl) == ("x", "x")
